  ('xm-199-phoenix', 'Main Thrusters (2, forward section)', 200, 'each', 9),
  ('xm-199-phoenix', 'Secondary Thrusters (2, tail)', 80, 'each; small target: called shot only, attacker -3 to strike', 10),
  ('xm-199-phoenix', 'Carrying Pylons (3)', 220, 'each', 11),
  ('xm-199-phoenix', 'Reinforced Pilot Compartment', 150, NULL, 12),
  ('xm-199-phoenix', 'Force Field', 200, 'depleting it shuts the field down; damage then goes to the main body; regenerates in six hours (33 M.D.C. per hour)', 13),
  ('xm-199-phoenix', 'Main Body', 400, 'depleting it shuts the aircraft down; it crashes if in flight', 14);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('x-1471-wolfhound', 1, 'Shoulder Laser Cannon (1)', '1D4x10 M.D. per single blast', 1, '4,000 feet (1,219 m)', 'Equal to the number of hand to hand attacks of the pilot', 'Effectively unlimited', NULL, 'Right shoulder; main weapon, capable of single and double fire, 90 degree arc of fire. Anti-Aircraft/Gargoyles and Assault.'),
  ('x-1471-wolfhound', 2, 'Shoulder Rail Gun (1)', '6D6 M.D. per 15 round short burst or 1D6x10 M.D. per 30 round long burst of DU- or U-rounds', 1, '4,000 feet (1219 m)', 'Each short or long burst counts as one melee attack', '3,900 rounds, for a total of 130 long bursts', NULL, 'Left shoulder, gatling-style; fires bursts only, any rail gun ammunition, DU rounds standard.'),
  ('x-1471-wolfhound', 3, 'Mini-Missile Launchers (3)', 'Varies with missile type; fragmentation (5D6 M.D. to everything in a 20 foot/6.1 m radius) is the standard load', 1, 'Varies with missile type; fragmentation half a mile (0.8 km)', 'One at a time or in volleys of 2, 4, 6 or 12', '48 total, 16 in each of the three shoulder launchers', NULL, 'Three box launchers in one segmented housing over the left shoulder; lids open to fire and close after.'),
  ('x-1471-wolfhound', 4, 'Eye Lasers (2)', '2D6 M.D. per single blast or 4D6 M.D. per double blast', 1, '1,600 feet (488 m)', 'Each single or dual simultaneous blast at the same target counts as one melee attack', 'Effectively unlimited', NULL, 'Light lasers modeled on the EIR Gurgoyle Drone''s; anti-personnel and defense.'),
  ('x-1471-wolfhound', 5, 'Claw Vibro-Blades (4)', '4D6+8 M.D. per claw strike (factors in Robot P.S.)', 1, 'Hand to hand combat', NULL, NULL, NULL, 'Also give traction for running and climbing.'),
  ('x-2010-longstrike', 1, 'Modular, Quick-Replacement, Long-Range Missile Pods (2)', 'Varies with missile type. Standard payload: 80% Heavy High Explosive (4D6x10 M.D. to everything in a 40 foot/12.2 m blast radius, 500 mile/800 km range); 10% Nuclear Multi-Warhead (2D4x100 M.D. to a 50 foot/15.2 blast radius, 1,800 mile/2,880 km range); 10% Plasma (5D6x10 M.D. to everything in a 50 foot/15.2 m blast radius, 500 mile/800 km range, for non-Gargoyle enemies)', 1, 'Varies with missile type, 500-1,800 miles (800 to 2,880 km)', 'One at a time or in volleys of 2, 4, 6, 8, 12, 16, 20, or all 48 (24 per missile launcher)', '48 long-range missiles total, 24 per launcher. Reloaded within 1D4+5 minutes with the proper gear; medium-range missiles can be substituted (same number).', '+5 to strike (smart missiles)', 'Box launchers in place of arms, 180 degree arc of fire. Gargoyles and most demons are impervious to the plasma missiles; Brodkil take full damage.'),
  ('x-2010-longstrike', 2, 'Gatling-Style Rail Guns (2)', '6D6+3 M.D. per 15 round short burst or 1D6x10+10 M.D. per 30 round long burst of DU- or U-Rounds', 1, '4,000 feet (1,219 m)', 'Each burst, short or long, counts as one melee attack', '6,000 rounds per gun, for a total of 200 long bursts', NULL, 'Top turrets that rotate 360 degrees and fire over the launchers; bursts only. The pilot fires them while the gunner launches missiles, or the gunner can take them over.'),
  ('x-2010-longstrike', 3, 'Dragonwing Weapon Arms (2)', 'Laser: 1D4x10 M.D. per single blast or 2D4x10 M.D. when both arms fire at the same target. Ion Cannon: 1D4x10 M.D. per single blast or 2D4x10 M.D. when both arms fire at the same target', 1, 'Laser: 6,000 feet (1,829 m). Ion Cannon: 2,000 feet (610 m).', 'Each single or simultaneous dual blast counts as one melee attack', 'Effectively unlimited', NULL, 'Same arms as the Dragon Wing, mounted under the chest plates; laser top barrel, ion cannon bottom. Always fired by the pilot; can also strike and parry in melee.'),
  ('x-2020-rainmaker', 1, 'Recoilless Anti-Aircraft Auto-Cannon (1)', '1D4x10 M.D. per dual, two round simultaneous shot (5 foot/1.5 m blast radius); 1D6x10 M.D. per four round burst or 2D6x10+12 M.D. per eight round rapid-fire burst (15 foot/4.6 m blast radius)', 1, '20,000 feet (6,096 m)', 'Each dual shot or burst counts as one of the gunner''s melee attacks', '3,200 rounds total; 800 four round bursts or 400 eight round bursts', '+2 to strike on automatic fire, with 6 attacks per melee; sensor bonus +2 to strike when crewed', 'Double-barreled top turret at the back; 360 degree rotation, 120 degree up and down arc. Always run by an independent gunner, or switched to automatic, where it either shoots two- or four-round bursts at whichever enemy is closest or engages only fast incoming targets (usually missiles). The sensor notes call it the Recoilless Anti-Aircraft Flak Cannon.'),
  ('x-2020-rainmaker', 2, 'Medium-Range Missile Launcher (2)', 'Varies with missile type, but typically high explosive (3D6x10 M.D. to a 30 foot/9.1 m radius) or fragmentation (2D6x10 M.D. to a 40 foot/12.2 m radius)', 1, 'Varies with type of missile used, but typically 40 miles (64 km)', 'Volleys of 2, 4, 6, 10 or 12; each volley counts as one melee attack', '44 total medium-range missiles, 22 in each launcher', NULL, 'One on each side; rotates 180 degrees from forward to straight up to rearward. Either the gunner or the co-pilot operates it.'),
  ('x-2020-rainmaker', 3, 'Mini-Missile Launcher (4)', 'Varies with missile type; half the load is typically fragmentation (5D6 M.D. to everything within a 20 foot/6.1 m radius), the other half armor piercing (5D6 M.D. to a 3 foot/0.9 m radius)', 1, 'Varies with type of missile used: half mile (0.8 km) for fragmentation, one mile for armor piercing', 'One at a time or in volleys of 2, 4 or 8', '64 total, 16 mini-missiles in each leg launcher', NULL, 'Concealed in each lower leg behind a sliding armored panel.'),
  ('x-2020-rainmaker', 4, 'Forward Rail Gun Turret (1)', '6D6+3 M.D. for a 15 round short burst or 1D6x10+10 M.D. per 30 round long burst', 1, '6,000 feet (1,829 m)', 'Each burst counts as one of the pilot or co-pilot''s melee attacks', '3,000 rounds per weapon, enough for 100 long bursts', NULL, 'Gatling-style, under the forward cockpit; used mainly against ground troops.'),
  ('x-2525-faust', 1, 'Forearm Buzz Saws (2)', '1D6x10+6 M.D. with the blades spinning; 1D6 M.D. plus punch damage when turned off', 1, 'Melee combat', NULL, 'Effectively unlimited', NULL, 'Circular blades housed in the upper forearms that slide down and lock above the hands.'),
  ('x-2525-faust', 2, 'Energy Fists (2)', '+10 M.D. to punch damage (6D6 M.D. on a full strength punch); electric discharge 5D6 M.D.', 1, 'Melee combat or electrical discharge 400 feet (122 m)', NULL, 'Effectively unlimited', NULL, 'Electrically charged hands like the TX-H1 Electro-Mace.'),
  ('x-2525-faust', 3, '"Slammer" Concussion Missile Launcher (1, chest)', '2D4x10 M.D. from a direct hit; the concussion does 1D4x10 M.D. to all within a 45 foot (13.7 m) blast radius, who are likely (01-88%) knocked off their feet and stunned (01-65%)', 1, '6,000 feet (1,829 m)', 'One at a time', '12 total; as one is fired another cycles into the launch chamber', NULL, 'Single-shot launcher in the chest''s circular impression. Knocked down: lose one melee attack and initiative; a direct hit always knocks the victim down. Stunned: -10 to strike, parry, dodge, roll with impact and pull punch, last to attack, half attacks and half speed for 1D4 melee rounds.'),
  ('x-2525-faust', 4, 'Leg Mounted Mini-Missiles', 'Varies with missile type; fragmentation (5D6 M.D. to everything in a 20 foot/6.1 m radius) is the standard load', 1, 'Varies with missile type; fragmentation half a mile (0.8 km)', 'One at a time or in volleys of 2, 4, 6, 8, 10 or all 30', '30 total; 15 mini-missiles in each launcher', NULL, 'A panel on the outer side of each lower leg slides open to fire.'),
  ('x-2525-faust', 5, 'TX-H Series', NULL, 1, NULL, NULL, NULL, NULL, 'Can wield any TX-H series melee weapon.'),
  ('x-2730-griffon', 1, 'Ion Cannon Nose Gun (1)', '1D4x10 M.D. per single blast', 1, '1,000 feet (305 m)', 'Each blast counts as one of the pilot''s melee attacks', 'Effectively unlimited', NULL, 'The upside-down triangle on the head; short-range, fires wherever the nose points.'),
  ('x-2730-griffon', 2, 'Roll-Back Mini-Missile Launchers (1, back)', 'Varies with missile type; fragmentation (5D6 M.D. to everything in a 20 foot/6.1 m radius) is the standard load', 1, 'Varies with missile type; fragmentation half a mile (0.8 km)', 'One at a time or in volleys of 2, 4 or 6', '48 total mini-missiles', NULL, 'Panels behind the head roll back to reveal the launcher.'),
  ('x-2730-griffon', 3, 'Forearm Vibro-Blade Claws (3 per hand)', '3D6+10 M.D. per claw strike (factors in Robot P.S.)', 1, 'Hand to hand combat', NULL, NULL, NULL, 'Hooked blades; also used to pry, tear and climb.'),
  ('x-2730-griffon', 4, 'Feet Vibro-Blade Claws (3 per foot)', '4D6 M.D. + Kick or Leap Kick damage when applicable', 1, 'Hand to hand combat', NULL, NULL, NULL, 'Usually used from a leap attack or a hover; also help it climb.'),
  ('x-2750-talon', 1, 'Chest "Slammer" Concussion Missile Launchers (2)', '2D4x10 M.D. from a direct hit; the concussion does 1D4x10 M.D. to all within a 45 foot (13.7 m) blast radius, who are likely (01-88%) knocked off their feet and stunned (01-65%)', 1, '6,000 feet (1,829 m)', 'One at a time', '20 total, 10 per launcher; as one is fired another cycles into the launch chamber', NULL, 'Concealed in the chest either side of the pilot compartment behind flip-open covers. Knocked down: lose one melee attack and initiative; a direct hit always knocks the victim down. Stunned: -10 to strike, parry, dodge, roll with impact and pull punch, last to attack, half attacks and half speed for 1D4 melee rounds.'),
  ('x-2750-talon', 2, 'Rail Gun Weapon Arms', '5D6 M.D. per 15 round short burst, 1D4x10 M.D. per 30 round burst of U-Rounds, or 2D4x10 M.D. if both weapons fire at the same target simultaneously', 1, '4,000 feet (1,219 m)', 'Each burst counts as one of the pilot or co-pilot''s melee attacks', '3,000 rounds per weapon, enough for 100 long bursts each', NULL, 'A pair of small rail guns in the rib cage area. Gargoyles cannot bio-regenerate damage from U-Rounds for 1D6 hours.'),
  ('x-2750-talon', 3, 'Forearm Vibro-Blade Swords (4)', '1D4x10+8 M.D. per double blade attack (factors in Robot P.S. damage)', 1, '12 foot (3.6 m) reach', NULL, NULL, NULL, 'Two long, extendible and retractable Vibro-Swords on each forearm.'),
  ('x-2750-talon', 4, 'Concealed Mini-Missile Launchers (2)', 'Varies with missile type; fragmentation (5D6 M.D. to everything in a 20 foot/6.1 m radius) is the standard load', 1, 'Varies with missile type; fragmentation half a mile (0.8 km)', 'One at a time or in volleys of 2, 4, 6, 8, 12 or 24', '24 total, 12 mini-missiles in each launcher', NULL, 'One concealed in each lower leg.'),
  ('x-2750-talon', 5, 'Giant M.D. Rifle or TX-H Series Weapon', NULL, 1, NULL, NULL, NULL, NULL, 'Any giant handheld weapon, usually carried; TX-H series melee weapons also usable but seldom needed. Can drop bombs (they inflict short-range missile damage and get no strike bonus) or position VS-101 Sonic Stun Projectors.'),
  ('x-4500-gunman', 1, 'TX-4501 Shoulder-Mounted, High-Intensity Laser Cannon (1)', '1D4x10 M.D. per blast', 1, '8,000 feet (2,438 m)', 'Single shots only, each blast counts as one melee attack', 'Effectively unlimited', '+1 to strike on an Aimed or Called Shot', 'Role: anti-armor (main), anti-aircraft/Gargoyles (secondary). The main gun, on the shoulder track with its own mini-turret: 360 degree rotation and a 90 degree up and down arc; no recoil.'),
  ('x-4500-gunman', 2, '"Slammer" Concussion Missile Launcher (1)', '2D4x10 M.D. direct hit; the concussion does 1D4x10 M.D. to all within a 45 foot (13.7 m) blast radius, with a 01-88% chance to knock them down and 01-65% to stun them', 1, '6,000 feet (1,828 m)', 'One at a time', '10 total', NULL, 'Role: anti-Gurgoyle/Gargoyle (main), anti-personnel (secondary). Over the right shoulder; the blast radius is printed "45 feet (13.7 m) in diameter" here. Knocked down: lose one melee attack and initiative; a direct hit always knocks the target down. Stunned: -10 to strike, parry, dodge, roll with impact and pull punch, last to attack, half the attacks per melee and half speed for 1D4 melee rounds.'),
  ('x-4500-gunman', 3, 'Forearm-Mounted Pulse Lasers (2)', '3D6 M.D. per single shot or 1D4x10 M.D. per triple pulse blast', 1, '4,000 feet (1,219 m)', 'Each single shot or pulse counts as one melee attack', 'Effectively unlimited', NULL, 'Role: assault and anti-personnel (main), defense (secondary). Both cannot be fired simultaneously at the same target; the hands stay free.'),
  ('x-4500-gunman', 4, 'Rail Gun Weapon Arms', '5D6 M.D. per 15 round short burst, 1D4x10 M.D. per 30 round burst of U-rounds, or 2D4x10 M.D. if both fire at the same target simultaneously', 1, '4,000 feet (1,219 m)', 'Each burst counts as one melee attack', '3,000 rounds per weapon, enough for 100 long bursts each', NULL, 'Role: anti-Gargoyle and anti-aircraft (main), anti-personnel (secondary). A pair in the rib cage; U-rounds stop Gargoyle bio-regeneration for 1D6 hours.'),
  ('x-4500-gunman', 5, 'Leg-Mounted Mini-Missiles', 'Varies with missile type; fragmentation is standard (5D6 M.D. to everything in a 20 foot/6.1 m radius)', 1, 'Varies with missile type; fragmentation is a half a mile (0.8 km)', 'One at a time or in volleys of 2 or 4', '16 total, eight in each leg launcher', NULL, 'Role: anti-Gargoyle and anti-armor (main), anti-personnel and defense (secondary). Extend from the lower legs to fire.'),
  ('x-4500-gunman', 6, 'Optional Shoulder Weapon Systems (1): TX-4502 Shoulder-Mounted, Supercharged Ion Cannon', '2D4x10 M.D. per blast', 1, '4,000 feet (1219 m)', 'Each shot counts as one melee attack', 'Effectively unlimited', NULL, 'Optional replacement for the Slammer launcher or laser cannon. Role: anti-robot and anti-armor (main), assault and troop support (secondary).'),
  ('x-4500-gunman', 7, 'Optional Shoulder Weapon Systems (1): TX-4503 Shoulder Mounted Particle Beam', '2D4x10+10 M.D. per blast; double damage on an unmodified Natural 19 or 20', 1, '3,000 feet (914 m)', 'Single shots only', 'Effectively unlimited', NULL, 'Optional replacement shoulder weapon for assaults on hardened and fortified targets. Role: assault (main), anti-armor/anti-Gurgoyle (secondary).'),
  ('x-4500-gunman', 8, 'Optional Shoulder Weapon Systems (1): TX-4504 Shoulder-Mounted Rapid-Fire Grenade Launcher', '4D6 M.D. to a 10 foot (3 m) radius, or 2D4x10 M.D. to everything in a 25 foot (7.6 m) radius per four round burst', 1, '1,400 feet (427 m)', 'Each single shot or burst counts as one melee attack', '200 grenades, enough for 50 bursts', NULL, 'Optional replacement shoulder weapon. Role: anti-personnel (main), defense (secondary).'),
  ('x-4500-gunman', 9, 'TX-H Series', NULL, 1, NULL, NULL, NULL, NULL, 'One or two M.D. melee weapons from the TX-H series, clipped to the hips when not in use.'),
  ('x-4600-sharpshooter', 1, 'TX-4601 Long Rifle (Rail Gun)', '2D4x10 M.D. per single round', 1, '10,000 feet (3,048 m; close to two miles/3.2 km)', 'Each shot counts as one of the shooter''s melee attacks; single shot only', '60 round, auto-feed', '+2 on an Aimed or Called Shot; Critical Hit on an unmodified Natural 18, 19 or 20', 'Role: long-range precision sniper strikes (main), anti-personnel (secondary). The round leaves on a powder charge, is accelerated by electromagnetic coils, then fires a ramjet.'),
  ('x-4600-sharpshooter', 2, 'Forearm Mini-Missile Launch Tubes (6 total)', 'Varies with missile type; fragmentation is standard (5D6 M.D. to everything in a 20 foot/6.1 m radius)', 1, 'Varies with missile type; fragmentation is a half a mile (0.8 km)', 'One at a time or in volleys of 2 or 4', '12 total, two in each launcher', NULL, 'Role: anti-Gargoyle and anti-armor (main), anti-personnel and defense (secondary). Three tubes per forearm.'),
  ('x-4600-sharpshooter', 3, 'Optional: Handheld Rifle', NULL, 1, NULL, NULL, NULL, NULL, 'May carry a robot-sized handheld weapon such as the TX-222 (Weapons section, p.102), though most do not.'),
  ('x-4600-sharpshooter', 4, 'TX-H Series', NULL, 1, NULL, NULL, NULL, NULL, 'Any TX-H series hand to hand weapon (p.103); pilots like a pair of Vibro-Blades on the lower leg or hip.'),
  ('x-5050-black-death', 1, 'Super PBA Main Cannon Turret: Particle Beam Cannon (Main Gun)', '1D6x100 M.D. per single blast; double damage on an unmodified Natural 19 or 20', 1, '8,000 feet (2438 m)', 'Each shot counts as one of the gunner''s melee attacks', 'Effectively unlimited', '+1 to strike from an independent coordinated targeting system', 'Role: anti-fortification/anti-armor (main), assault (secondary). A smaller version of the Super PBA Cannon of the Mobile Infantry Strike Base (Rifts Sourcebook 3: Mindwerks), in an armored turret with 360 degree rotation and a 45 degree up and down arc; dedicated gunner.'),
  ('x-5050-black-death', 2, 'Super PBA Main Cannon Turret: Heavy Laser (Secondary Weapon)', '6D6 M.D. per blast', 1, '6,000 feet (1,829 m)', 'Single shots only, each blast counts as one of the gunner''s melee attacks', 'Effectively unlimited', '+1 to strike on an Aimed or Called Shot', 'Role: anti-armor and anti-aircraft/Gargoyles (main), assault and defense (secondary). Single barrel above the main gun as a backup and precision weapon; the turret gunner cannot fire it and the particle beam simultaneously.'),
  ('x-5050-black-death', 3, 'Single-Barrel Heavy Rail Gun Turret (1)', '1D4x10 M.D. per 20 round short burst or 1D6x10 M.D. per 40 round long burst', 1, '6,000 feet (1,829 m)', 'Each short or long burst counts as one melee attack of the gunner', '10,000 rounds each for 250 long bursts', NULL, 'Role: assault and anti-personnel (main), defense (secondary). In the nose, rotates 360 degrees with a 30 degree arc; fires bursts only, standard ammo (not DU- or U-rounds); dedicated gunner.'),
  ('x-5050-black-death', 4, 'Heavy Double-Barrel Rail Gun Turrets (3)', '1D6x10 M.D. per 40 round single barrel burst or 2D6x10 M.D. per double barrel burst', 1, '6,000 feet (1,829 m)', 'Each single or dual barrel burst counts as one melee attack of the gunner', '12,000 rounds each for 150 dual barrel bursts', NULL, 'Role: assault (main), defense (secondary). One at the back and one on each side of the mid-section, each rotating 180 degrees with a 45 degree arc; bursts only, standard ammo (not DU or U rounds); dedicated gunner.'),
  ('x-5050-black-death', 5, 'Laser Cannons (2)', '5D6 M.D. per single blast', 1, '4,000 feet (1,219 m)', 'Single shots only, each blast counts as one melee attack of the dedicated gunner', 'Effectively unlimited', '+1 to strike on an Aimed or Called Shot', 'Role: anti-armor and anti-aircraft/Gargoyles (main), assault and defense (secondary). One on each side of the pilot compartment, each with its own gunner.'),
  ('x-5050-black-death', 6, 'Forward Short-Range Missile Launcher (1)', 'Varies with missile type; typically high-explosive (2D6x10 M.D. to everything in a 15 foot/4.6 m radius) or fragmentation (2D4x10 M.D., 20 foot/6.1 m radius)', 1, 'Varies with missile type; high-explosive five miles (8 km), fragmentation three miles (4.8 km)', 'One at a time or in volleys of 2, 4 or 8', '48 total missiles', NULL, 'Role: anti-aircraft/Gargoyles and assault (main), defense (secondary). Built into the nose.'),
  ('x-5050-black-death', 7, 'Front Leg Mini-Missile Launchers (2)', 'Varies with missile type; fragmentation is standard (5D6 M.D. to everything in a 20 foot/6.1 m radius)', 1, 'Varies with missile type; fragmentation is a half a mile (0.8 km)', 'One at a time or in volleys of 2 or 4', '60 total, 30 in each front leg launcher', NULL, 'Role: anti-Gargoyle and anti-armor (main), anti-personnel and defense (secondary). A panel in each front leg slides open to fire.'),
  ('x-5050-black-death', 8, 'Medium-Range Missile Launcher Turret (1)', 'Varies with missile type; typically high-explosive (3D6x10 M.D. to everything in a 30 foot/9.1 m radius) or Multi-Warhead smart bomb (5D6x10 M.D. to a 20 foot/6.1 m radius); often half and half', 1, 'Varies with missile type; typically 40 miles (64 km)', 'One at a time or in volleys of 2, 4, 6 or 8', '42 total medium-range missiles', NULL, 'Role: anti-fortified positions and anti-armor (main), anti-Gargoyle and assault (secondary). Near the tail, rotates 360 degrees with a 45 degree arc; the prose says it engages aerial targets and Gargoyles.'),
  ('x-5001-devastator-mk-ii', 1, 'TX-5050 Super-Laser Cannon (1, Rifle)', '1D6x10 M.D. per low power blast or 2D6x10 M.D. per single full power blast; 50% more damage on a Critical Strike from an unmodified Natural 18, 19 or 20', 1, '8,000 feet (2,438 m)', 'Each blast, low or full power, counts as one of the gunner or co-pilot''s melee attacks', 'Effectively unlimited', '+1 to strike in addition to other targeting bonuses', 'Role: anti-armor/anti-aircraft/Gargoyles (main), assault (secondary). The huge handheld rifle, an advance on the original Devastator''s; operated by either the co-pilot or its own gunner.'),
  ('x-5001-devastator-mk-ii', 2, 'TX-5051 Super-Ion Cannon (1)', '4D6x10 M.D. per single full power blast', 1, '6,000 feet (1,829 m)', 'Each blast counts as one of the gunner''s melee attacks', 'Effectively unlimited', '+1 to strike from the coordinated targeting system', 'Role: anti-fortifications, anti-armor and aircraft (main), assault (secondary). Mounted on the back, swings over the right shoulder to fire forward but can fire even when stowed; dedicated gunner.'),
  ('x-5001-devastator-mk-ii', 3, 'Long-Range Missile Launcher (1)', 'Varies with missile type; standard issue is 12 heavy high explosive (4D6x10 M.D. to everything in a 40 foot/12.2 m blast radius), 2 plasma (5D6x10 M.D., 50 foot/15.2 m blast radius) and 2 nuclear (heavy, 1D6x100 M.D., 50 foot/15.2 m blast radius)', 1, 'Varies with missile type; heavy high explosive and plasma 500 miles (800 km), heavy nuclear 1,000 miles (1,600 km)', 'One at a time or in volleys of 2, 4 or 6', '16 total long-range missiles', NULL, 'Role: anti-armor and fortified positions (main), anti-aircraft and assault (secondary). Behind double doors in the center of the chest; dedicated gunner. The Range line gives a mix of 12 high explosive, 4 plasma and 4 nuclear (20) while the damage line gives 12, 2 and 2 (16, matching the payload); stored as printed.'),
  ('x-5001-devastator-mk-ii', 4, 'Medium-Range Missile Launchers (2)', 'Varies with missile type; typically high-explosive (3D6x10 M.D. to everything in a 30 foot/9.1 m radius) or Multi-Warhead smart missile (5D6x10 M.D. to a 20 foot/6.1 m radius); often half and half', 1, 'Varies with missile type; typically 40 miles (64 km)', 'One at a time or in volleys of 2, 4, 6 or 8', '24 total medium-range missiles, 12 per launcher', NULL, 'Role: anti-fortified positions and anti-armor (main), anti-Gargoyle and assault (secondary). Concealed on the back either side of the Super-Ion Cannon; typically fired by the co-pilot.'),
  ('x-5001-devastator-mk-ii', 5, 'Mini-Missile Launchers (2)', 'Varies with missile type; fragmentation is standard (5D6 M.D. to everything in a 20 foot/6.1 m radius)', 1, 'Varies with missile type; fragmentation is a half a mile (0.8 km)', 'One at a time or in volleys of 2, 4, 6, 8, 12 or 24', '96 total, 48 per mini-missile launcher', NULL, 'Role: anti-personnel (main), assault and defense (secondary). One on each side of the rib cage; typically the pilot or co-pilot.'),
  ('x-5001-devastator-mk-ii', 6, 'Slammer Concussion Missile Launchers (2)', '2D4x10 M.D. direct hit; the concussion does 1D4x10 M.D. to all within a 45 foot (13.7 m) blast radius, with a 01-88% chance to knock them down and 01-65% to stun them', 1, '6,000 feet (1,828 m)', 'One at a time', '24 total, 12 per launcher', NULL, 'Role: anti-Gurgoyle/Gargoyle (main), anti-personnel (secondary). Concealed in the lower legs; usually fired by the belly gunner. Knocked down: lose one melee attack and initiative; a direct hit always knocks the target down. Stunned: -10 to strike, parry, dodge, roll with impact and pull punch, last to attack, half the attacks per melee and half speed for 1D4 melee rounds.'),
  ('x-5001-devastator-mk-ii', 7, 'Ion Belly Gun Turret (1)', '4D6 M.D. per single blast or 1D4x10 M.D. per dual simultaneous blast', 1, '4,000 feet (1,219 m)', 'Each single or dual blast counts as one of the gunner''s melee attacks', 'Effectively unlimited', NULL, 'Role: anti-personnel (main), defense (secondary). Tilts 90 degrees up and down and 45 degrees left and right; dedicated gunner.'),
  ('x-5001-devastator-mk-ii', 8, 'Dual Forearm Weapon Housing: Forearm Vibro-Swords (2)', '1D6x10 M.D. including damage from Robot P.S. of 60', 1, NULL, NULL, NULL, '+1 to parry and disarm', 'Role: melee combat (main), defense (secondary). A retractable Vibro-Sword under the Boom Gun in each forearm housing.'),
  ('x-5001-devastator-mk-ii', 9, 'Dual Forearm Weapon Housing: Forearm Mounted Boom Gun (2)', '3D6x10 M.D. per blast', 1, '11,000 feet (3,353 m)', 'Each blast counts as one melee attack', '600 rounds total, 300 rounds per Boom Gun', NULL, 'Role: anti-armor and anti-Gargoyle (main), assault and defense (secondary). A last-resort weapon controlled by the pilot; no recoil system needed. Anyone without ear protection within 200 feet (61 m) is deafened for 2D4 minutes at -8 initiative and -3 to parry and dodge (half time and penalties inside NGR armor and robots); the boom shatters windows and shakes buildings within 300 feet (91.5 m), double when both fire together.'),
  ('x-5001-devastator-mk-ii', 10, 'The "Shocker" Electric Field Generator', '2D6 M.D. every 4 seconds to everything touching the exterior surface', 1, 'The outer hull of the robot', 'Four shocks of 2D6 M.D. each per melee round', 'Up to two minutes (8 melee rounds) at a time before shutting off; can be restarted after 30 seconds (two melee rounds); effectively unlimited', NULL, 'Primary purpose defense. Damage goes to armor first. 01-66% chance the first jolt makes anyone holding, hitting or climbing on it let go, losing initiative and one melee attack; damage is cumulative for those who hang on. Missiles cannot be launched while it is up.'),
  ('xm-350-rhino', 1, 'Main Turret: Heavy, Dual Particle Beam (1)', '2D4x10+4 M.D. per single blast, 4D4x10+8 M.D. when both barrels are fired in tandem; Critical Strike (double damage) on a Natural 19 or 20', 1, '3,000 feet (914 m)', 'Each single or dual blast counts as one melee attack', 'Effectively unlimited', '+1 to strike (design bonus)', 'Role: anti-armor and anti-fortifications (main), anti-Gargoyle and assault (secondary). Turret rotates 360 degrees with a 45 degree up and down arc; fired by the pilot or co-pilot.'),
  ('xm-350-rhino', 2, 'Pulse Laser Turrets (3)', '3D6+3 M.D. per single shot or 1D6x10 M.D. per triple pulse blast', 1, '4,000 feet (1,219 m)', 'Each single shot or triple blast counts as one attack', 'Effectively unlimited', '+2 to strike (design bonus)', 'Role: defense (main), anti-personnel (secondary). One front and one on each side, each rotating 90 degrees side to side with a 25 degree up and down arc.'),
  ('xm-350-rhino', 3, 'Mini-Missile Launchers (1)', 'Varies with missile type; most common are high-explosive (1D4x10 M.D.) or fragmentation (5D6 M.D., 20 foot/6.1 m radius)', 1, 'One mile (1.6 km) for high-explosive and a half a mile for fragmentation (printed "0.8 m", meaning 0.8 km)', 'One at a time or in volleys of 2, 4 or 6', '12 explosive mini-missiles total, plus two smoke missiles', NULL, 'Role: anti-aircraft (main), anti-personnel (secondary). A box launcher at the back above the sensor turret.'),
  ('xm-279-earth-lifter', 1, 'Forward Particle Beams (2)', '1D6x10+10 M.D. per single blast; Critical Strike (double damage) on a Natural 19 or 20; both together at one target 2D6x10+10 M.D.', 1, '4,000 feet (1,219 m)', 'Each single or dual blast counts as one of the gunner''s melee attacks', 'Effectively unlimited', NULL, 'Role: defense (main), anti-Gargoyle/aircraft and assault (secondary). Behind the crew compartment; they rotate 360 degrees but have only a 20 degree outward arc, and can only fire together at one target at least 100 feet (printed "27.4 m") wide. Each has a dedicated gunner; used to clear landing zones.'),
  ('xm-279-earth-lifter', 2, 'Short-Range Missile Launchers (2)', 'Varies with missile type; most common are high-explosive (2D6x10 M.D. to a 15 foot/4.6 m radius) or fragmentation (2D4x10 M.D. to a 20 foot/6.1 m radius)', 1, 'Varies with missile type; high-explosive five miles (8 km), fragmentation three miles (4.8 km)', 'One at a time or in volleys of 2, 4, 8 or 16', '96 total missiles, 48 in each launcher', NULL, 'Role: defense (main), anti-aircraft/Gargoyles and assault (secondary). On top, off to the sides; fired by a gunner or the co-pilot.'),
  ('xm-279-earth-lifter', 3, 'Rear Laser Turret (1)', '6D6 M.D. per single blast', 1, '6,000 feet (1,829 m)', 'Each blast counts as one of the gunner''s melee attacks', 'Effectively unlimited', NULL, 'Role: defense (main), anti-Gargoyle/aircraft and assault (secondary). Above the rear jet thrusters; rotates 360 degrees with a 220 degree arc; dedicated gunner.'),
  ('xm-279-earth-lifter', 4, 'Concealed Rail Gun Turrets (2)', '6D6 M.D. per 30 round short burst or 1D6x10 M.D. per 60 round long burst', 1, '6,000 feet (1829 m)', 'Each short or long burst counts as one melee attack of the pilot or co-pilot', '12,000 rounds each for 200 long bursts', NULL, 'Role: assault (main), defense (secondary). Extend from the undercarriage at the nose, rotate 360 degrees with a 180 degree arc toward the ground and rear; bursts only, standard ammo (not DU- or U-rounds); a reload needs a skilled gunner or technician and roughly an hour. The M.D.C. table lists four.'),
  ('xm-199-phoenix', 1, 'Main Gun/Laser Turret (1)', '2D4x10 M.D. per single blast', 1, '4,000 feet (1,219 m)', 'Each blast counts as one of the gunner''s attacks', 'Effectively unlimited', NULL, 'Role: assault (main), anti-armor (secondary). Double-barreled turret in the nose, rotates 360 degrees with a 220 degree arc; dedicated gunner.'),
  ('xm-199-phoenix', 2, 'Rail Gun Turret (1, rear)', '6D6 M.D. per 30 round short burst or 1D6x10 M.D. per 60 round long burst', 1, '4,000 feet (1,219 m)', 'Each short or long burst counts as one melee attack of the gunner', '6,000 rounds each for 100 long bursts', NULL, 'Role: assault (main), defense (secondary). Double-barreled turret in the tail, rotates 360 degrees with a 180 degree arc; bursts only, standard ammo (not DU- or U-rounds); dedicated gunner.'),
  ('xm-199-phoenix', 3, 'Short-Range Missiles (2)', 'Varies with missile type; typically high-explosive (2D6x10 M.D. to everything in a 15 foot/4.6 m radius) or fragmentation (2D4x10 M.D., 20 foot/6.1 m radius), or a combination', 1, 'Varies with missile type; high explosive five miles (8 km), fragmentation three miles (4.8 km)', 'One at a time or in volleys of 2, 4, 8, 16 or 32', '32 total missiles; 16 in each launcher', NULL, 'Role: defense (main), anti-aircraft/Gargoyles and assault (secondary). A box launcher under each wing; usually the co-pilot or pilot.'),
  ('xm-199-phoenix', 4, 'Medium-Range Missile Launcher (2)', 'Varies with missile type; typically high-explosive (3D6x10 M.D. to everything in a 30 foot/9.1 m blast radius) or fragmentation (2D6x10 M.D., 40 foot/12.2 m radius)', 1, '40 miles (64 km) for both standard high explosive and fragmentation', 'One at a time or both at once', 'Two', NULL, 'Role: anti-aircraft/Gargoyles (main), defense (secondary). One medium-range missile on each wingtip; usually the pilot.'),
  ('xm-199-phoenix', 5, 'Anti-Missile Chaff Dispenser (1)', 'None; roll percentile: 01-50% the missile or volley detonates in the chaff, 51-75% it loses track and veers off (may lock onto nearby aircraft), 76-00% no effect', 0, NULL, NULL, '16', NULL, 'Primary purpose anti-missile. In the tail. Any Gargoyle or other flier that passes through the cloud suffers half speed, half melee attacks and half combat bonuses for 1D4 melee rounds.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 13 vessels are in and cite Triax 2' AS assertion, count(*) AS got, 13 AS want
  FROM vehicles WHERE source_book LIKE 'Rifts World Book 31: Triax 2 p.%' AND slug IN ('x-1471-wolfhound', 'x-2010-longstrike', 'x-2020-rainmaker', 'x-2525-faust', 'x-2730-griffon', 'x-2750-talon', 'x-4500-gunman', 'x-4600-sharpshooter', 'x-5050-black-death', 'x-5001-devastator-mk-ii', 'xm-350-rhino', 'xm-279-earth-lifter', 'xm-199-phoenix');
SELECT 'their 182 locations are in' AS assertion, count(*) AS got, 182 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('x-1471-wolfhound', 'x-2010-longstrike', 'x-2020-rainmaker', 'x-2525-faust', 'x-2730-griffon', 'x-2750-talon', 'x-4500-gunman', 'x-4600-sharpshooter', 'x-5050-black-death', 'x-5001-devastator-mk-ii', 'xm-350-rhino', 'xm-279-earth-lifter', 'xm-199-phoenix');
SELECT 'their 69 weapon entries are in' AS assertion, count(*) AS got, 69 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('x-1471-wolfhound', 'x-2010-longstrike', 'x-2020-rainmaker', 'x-2525-faust', 'x-2730-griffon', 'x-2750-talon', 'x-4500-gunman', 'x-4600-sharpshooter', 'x-5050-black-death', 'x-5001-devastator-mk-ii', 'xm-350-rhino', 'xm-279-earth-lifter', 'xm-199-phoenix');

